<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Szablony';?>
<div class="page-head"><div><p class="eyebrow">Administracja · Content</p><h1>Szablony</h1></div></div><?php if(isset($_GET['error'])):?><div class="alert danger">Nie udało się utworzyć szablonu.</div><?php endif;?><section class="card section-card"><h2>Nowy szablon</h2><form method="post" class="grid compact-form"><?=Csrf::field()?><label>Nazwa<input name="name" maxlength="150" required></label><label>Zakres<select name="space_id"><option value="0">Globalny</option><?php foreach($spaces as $s):?><option value="<?=Html::e($s['id'])?>"><?=Html::e($s['name'])?></option><?php endforeach;?></select></label><label>Opis<input name="description" maxlength="255"></label><label>Labels<input name="labels" placeholder="linux, dokumentacja"></label><label class="span-all">Properties JSON<textarea name="properties" rows="3" placeholder='{"status":"draft"}'></textarea></label><label class="span-all">Treść HTML<textarea name="content" rows="8"></textarea></label><div class="form-action"><button class="button">Utwórz</button></div></form></section><section class="card section-card"><h2>Szablony</h2><?php foreach($templatesList as $t):?><a class="list-row" href="<?=Html::e(Url::to('/admin/templates/'.$t['id']))?>"><span><strong><?=Html::e($t['name'])?></strong><small><?=Html::e($t['space_name']??'Globalny')?><?=$t['archived_at']?' · zarchiwizowany':''?></small></span></a><?php endforeach;?></section>
